            aOrbiterK = (aWandererI + RotL64(aScatter, 5U)) + 0x026909EB59D69A17ULL;
            aOrbiterA = ((aWandererK + RotL64(aPrevious, 41U)) + 0x992C58EA312F50D6ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterB = ((aWandererA + RotL64(aIngress, 13U)) + RotL64(aCarry, 29U)) + 0xA176797B63C5A8D3ULL;
            aOrbiterJ = ((aWandererG + RotL64(aScatter, 29U)) + 0x3C33387969D26470ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterC = (aWandererB + RotL64(aIngress, 35U)) + 0x02424826A2827CEBULL;
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 54U)) + RotL64(aCarry, 3U)) + 0x7D4391B2E2C0AB8CULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x1FC365B29B3D67AAULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xF25EB539D0B1309BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x60A2A70860E34B5BULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x0CBD471197B0EFCCULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x5091C9A2F5D2B050ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x95CE74B0CE18102BULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xCF11F8AAD4953503ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xE1863348F7AF3486ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x32B7C6C5B172C879ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xA3CA19954E3AAC49ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x07464E7BE67E4F06ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xA83019113140D511ULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x02E6ADAC07D7382EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x3AD0D94E95E063A7ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x87D90C9D23E083D3ULL), 41U);
