            aOrbiterC = ((aWandererD + RotL64(aPrevious, 47U)) + 0xD3F44EC3D59B0D7AULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterJ = ((aWandererC + RotL64(aCross, 19U)) + RotL64(aCarry, 39U)) + 0xC37463A46956C9DAULL;
