            aCross = (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 154U)) & S_BLOCK1], 41U) ^ RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 1073U)) & S_BLOCK1], 5U));
