            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterC, 35U));
            aIngress = aIngress + RotL64(aOrbiterF, 21U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aScatter, 47U) + aOrbiterF) + RotL64(aOrbiterC, 37U)) + RotL64(aCarry, 21U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 5U) + RotL64(aOrbiterJ, 27U)) + aOrbiterD);
            aWandererH = aWandererH + (((RotL64(aCross, 29U) + RotL64(aOrbiterA, 21U)) + aOrbiterD) + RotL64(aCarry, 57U));
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 21U) + RotL64(aOrbiterC, 5U)) + aOrbiterD);
            aWandererG = aWandererG + (((RotL64(aCross, 11U) + aOrbiterF) + RotL64(aOrbiterB, 52U)) + aKeyRotateWandererUpdateSaltD[((aIndex + 16U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 56U) + aOrbiterK) + RotL64(aOrbiterJ, 43U)) + aKeyRotateWandererUpdateSaltB[((aIndex + 27U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aIngress, 35U) + RotL64(aOrbiterA, 13U)) + aOrbiterC);
