            aCross = (RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 29583U)) & S_BLOCK1], 6U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 30359U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aIceLaneB[((S_BLOCK1 - aIndex + 28442U)) & S_BLOCK1], 19U) ^ RotL64(aLightningLaneB[((S_BLOCK1 - aIndex + 25455U)) & S_BLOCK1], 37U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aPrevious, 5U) ^ RotL64(aCross, 34U)) + (RotL64(aCarry, 19U) + RotL64(aIngress, 57U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterD = (aWandererJ + RotL64(aScatter, 39U)) + 0x577A38D046D32F0AULL;
            aOrbiterC = ((aWandererA + RotL64(aCross, 53U)) + 0xBA7D8FA03858B721ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 11U)) + RotL64(aCarry, 21U)) + 0x593BA8B150C82B5DULL;
            aOrbiterB = (aWandererH + RotL64(aIngress, 43U)) + 0xD407B0CBE4852551ULL;
            aOrbiterH = (aWandererB + RotL64(aPrevious, 58U)) + 0x7B278FEFA64F89E3ULL;
            aOrbiterE = ((aWandererI + RotL64(aScatter, 27U)) + RotL64(aCarry, 3U)) + 0x8CF3BCE19CBB487AULL;
            aOrbiterF = ((aWandererD + RotL64(aIngress, 35U)) + 0xCC7356AD469070D7ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterJ = (aWandererE + RotL64(aCross, 47U)) + 0x2598E9DB015A29DAULL;
            aOrbiterA = ((aWandererG + RotL64(aIngress, 22U)) + RotL64(aCarry, 43U)) + 0x1477B7D289937036ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xA4C2D383C4C93A7DULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x9E140C286B9DF8C8ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x196397DF89EA1AD1ULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x54C74D9C0DE7D98CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0xBC45695B6D6B08FBULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x06E40844088E4E79ULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0xF66E2F6CB6037D8AULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x1CAB4920B743CCDFULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x01BAD42FC630E5D7ULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x261A1F382A25679FULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x9E68AD52CD785B72ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x58634BE05F570A8BULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x058F2B37E5938904ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xA0526D7E49EC1975ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0283AB1112AB3495ULL), 39U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0xA0778E97239B8E80ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x16B0D2FEF24E8DE6ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xAF0D99515E39C505ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xA82D1E368FBEDCADULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0xF0E8C8DFC6E5E62CULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1F0DE398E5F8D749ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x72BB0877548F0FABULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xC8EEC8A44C5181DBULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xE6D2D8B46DA1293BULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x2551AE33B1942AF1ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0x3FBF38AF4F1F9D27ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 10U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x831D9FD8E7D4E30BULL), 53U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterG, 24U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterA, 57U));
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterC, 37U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterH, 27U));
            aIngress = aIngress + RotL64(aOrbiterJ, 47U);
