            aWandererB = aWandererB ^ ((RotL64(aIngress, 51U) + RotL64(aOrbiterH, 57U)) + aOrbiterD);
            aWandererD = aWandererD + (((RotL64(aPrevious, 57U) + aOrbiterA) + RotL64(aOrbiterB, 53U)) + RotL64(aCarry, 43U));
            aWandererG = aWandererG ^ (((RotL64(aCross, 6U) + aOrbiterF) + RotL64(aOrbiterA, 14U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 27U)) & S_SALT1]);
