            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 39U) ^ RotL64(aCarry, 53U)) + (RotL64(aIngress, 6U) + RotL64(aCross, 21U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 21U)) + RotL64(aCarry, 43U)) + 0xD60D3D4C0A45618FULL;
            aOrbiterJ = ((aWandererF + RotL64(aScatter, 23U)) + RotL64(aCarry, 47U)) + 0x44D7AE16AC70BD3FULL;
            aOrbiterH = (aWandererG + RotL64(aCross, 35U)) + 0x60D63CB1941D2556ULL;
            aOrbiterI = (aWandererK + RotL64(aIngress, 43U)) + 0xA20C5BD292C81ABDULL;
            aOrbiterA = ((aWandererC + RotL64(aCross, 60U)) + RotL64(aCarry, 19U)) + 0x91501467817B4DDAULL;
            aOrbiterC = (aWandererB + RotL64(aIngress, 39U)) + 0xF8C48338FD2C2741ULL;
            aOrbiterB = (aWandererI + RotL64(aScatter, 51U)) + 0x854BD7F14748BDB0ULL;
            aOrbiterK = ((aWandererJ + RotL64(aPrevious, 27U)) + 0x1E5BAB9DF5FAC608ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterD = ((aWandererE + RotL64(aCross, 10U)) + 0x7B39582059586EDCULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aPrevious, 29U)) + 0xB1632AE99931FDBAULL;
            aOrbiterF = (aWandererD + RotL64(aIngress, 57U)) + 0x2F0AABBA5542431BULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x5B2B0A5CDCE7988EULL;
