            aOrbiterK = RotL64((aOrbiterK * 0x6E1E09C26E60DD19ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x3EDD86D0E2C773B9ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xECBA95DDA373E214ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x92CE5EAE04901F7BULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xA47D2816C640F226ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xB1649EC6EED4112DULL;
