            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 25162U)) & S_BLOCK1], 43U) ^ RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 26195U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 30029U)) & S_BLOCK1], 22U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 24916U)) & W_KEY1], 53U));
