            aScatter = (RotL64(aPrevious, 41U) ^ RotL64(aCross, 23U)) ^ (RotL64(aIngress, 54U) + RotL64(aCarry, 11U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterJ = (aWandererG + RotL64(aCross, 19U)) + 0x82E1F06E0EE70E0FULL;
            aOrbiterC = ((aWandererK + RotL64(aIngress, 30U)) + RotL64(aCarry, 43U)) + 0x2C72F9D7472EDB07ULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 37U)) + 0xD01BC686098F06C9ULL;
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 13U)) + 0x9A86D265922EF592ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 20U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aCross, 5U)) + RotL64(aCarry, 29U)) + 0x4421CFE963669733ULL;
            aOrbiterE = (aWandererA + RotL64(aPrevious, 41U)) + 0x485559BB32EBFA4DULL;
            aOrbiterI = (aWandererE + RotL64(aIngress, 21U)) + 0xBC0AF7A24FADA87AULL;
            aOrbiterG = ((aWandererD + RotL64(aScatter, 53U)) + RotL64(aCarry, 11U)) + 0x9DA85398E7C7BBA1ULL;
            aOrbiterF = (aWandererC + RotL64(aCross, 56U)) + 0x1D29D7D0C0C30D98ULL;
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 23U)) + 0xB6F30606163182FEULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = (aWandererB + RotL64(aIngress, 51U)) + 0xB811C87C51C7C22DULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x54E67EE2B398C1F0ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x123719979A3808CFULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x8245837A6AD60CABULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x836F1AE2CD6D6754ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xE79AE9060A53931AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x320C3683AB27CA93ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x2A2B9CBC4E32AC39ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x224555A8A5784E50ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xA62E2035EB2910A9ULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x0EB6F4B7A9517F2CULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x74384370A8B87093ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xDA349112DF16D74DULL), 19U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xCE96D8952DA6D1F5ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x1BE5EEA5011B6F27ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE29BD88E59F1BD97ULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x8ECDC3F4D8227B41ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x31885EF5936ED0DFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x2CA8C81A34FB8BE3ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x1F7B9F737A320213ULL) + aKeyRotateOrbiterUpdateSaltC[((aIndex + 4U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x9A825CFCD93BBD22ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2FE89957AE0831CDULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x15A3517CA6820739ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x07D759E9A98BA05AULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8C63A0546548C567ULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x86898915CE71F021ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0xD2C14925992F6E2BULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x3BDACE6AB7768937ULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x2DDD3592EA9B3E29ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x64D63F227B871B79ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xE9F3E251874F4155ULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xCF99882E5540880DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xA5990B5822B4C73BULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEA1F084EA6F26383ULL), 13U);
