            aWandererB = aWandererB + (((RotL64(aCross, 57U) + RotL64(aOrbiterG, 3U)) + aOrbiterJ) + RotL64(aCarry, 51U));
            aWandererD = aWandererD ^ ((RotL64(aIngress, 41U) + RotL64(aOrbiterH, 53U)) + aOrbiterD);
            //
            aCarry = aCarry + (RotL64(aWandererA, 60U) ^ aWandererH);
            aCarry = aCarry + (RotL64(aWandererC, 29U) ^ aWandererB);
            aCarry = aCarry + (RotL64(aWandererE, 37U) ^ aWandererI);
