            aIngress = (RotL64(aKineticLaneA[((aIndex + 7758U)) & S_BLOCK1], 5U) ^ RotL64(aAetherLaneC[((aIndex + 10665U)) & S_BLOCK1], 21U));
            aIngress ^= (RotL64(aSoilLaneD[((aIndex + 10174U)) & S_BLOCK1], 37U) ^ RotL64(aVaporLaneA[((S_BLOCK1 - aIndex + 8623U)) & S_BLOCK1], 52U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 8403U)) & S_BLOCK1], 19U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 10046U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 7535U)) & S_BLOCK1], 39U) ^ RotL64(aWindLaneC[((aIndex + 7590U)) & S_BLOCK1], 10U));
            aCross = TwistMix64::DiffuseB(aCross);
