            aOrbiterJ = RotL64((aOrbiterJ * 0xEED5D35D1C5F07E7ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xD88947472EB86BEEULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xFCE3382D9348C288ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF5A5437EA4E45D97ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x1ADF9DA7510FDF3DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xE031271163715E34ULL;
