            aWandererJ = aWandererJ + ((((RotL64(aScatter, 51U) + RotL64(aOrbiterD, 21U)) + aOrbiterI) + RotL64(aCarry, 11U)) + aKeySpawnWandererUpdateSaltD[((aIndex + 15U)) & S_SALT1]);
