            aOrbiterH = ((aWandererE + RotL64(aPrevious, 28U)) + RotL64(aCarry, 43U)) + 0x5FB655DC9E9A663AULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x042BF7D20560FD0FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x19B54AE46C7137A4ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x9E73C959F0423635ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x67C8A9C85A953D1DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x78C73C1E3F5925E8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0DDC4F55937C26CDULL), 53U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xCFD60EE8FBAF59CEULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x3E754E862F7A4E16ULL) ^ aKeySpawnOrbiterUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xCD8234E565E6D76FULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xDC2D99D3417533C1ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xF9479E66D204235DULL;
            aOrbiterD = RotL64((aOrbiterD * 0x9B70107458D74AC5ULL), 29U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x06196849F7BA6234ULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
