            aOrbiterC = ((aWandererE + RotL64(aCross, 5U)) + RotL64(aCarry, 19U)) + 0xF7570730F3BF6422ULL;
            aOrbiterB = (((aWandererA + RotL64(aPrevious, 19U)) + RotL64(aCarry, 43U)) + 0x4064C8477170FC2AULL) + aKeySpawnOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterK = (aWandererJ + RotL64(aScatter, 60U)) + 0x1F42FEA3A507C58FULL;
            aOrbiterJ = (aWandererH + RotL64(aPrevious, 29U)) + 0xA624BDA271A22BE7ULL;
